// Technical atlas packing only; all character artwork is generated by image_gen.
// Run from repo root: node docs/pet-design/animation-01-06-2026-10-27/build.cjs
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const sharp=require('../../../apps/desktop/node_modules/sharp');
const root=__dirname;
const timing=JSON.parse(fs.readFileSync(path.resolve(root,'../../core-contracts.json'))).petFrameDurations;
const names=['idle','running-right','running-left','waving','jumping','failed','waiting','running','review'];
const labels=['空闲 / 已中断','进行中 · 右跑','左跑 · 完整兼容保留','等待输入 · 招手','已完成 · 庆祝','执行失败 · 受挫','状态待确认 · 张望','执行工具 · 工作','思考中 · 审阅'];
const mapping=['idle / interrupted','working','reserved directional motion','needs_input','complete','failed','unknown / unavailable','tool','thinking'];
const CW=192,CH=208,ROWS=9,COLS=8;
async function components(file,layout){
 const {data,info}=await sharp(file).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 const W=info.width,H=info.height,N=W*H,seen=new Uint8Array(N),groups=[],ids=new Int32Array(N);ids.fill(-1);
 const queue=new Int32Array(N);
 for(let i=0;i<N;i++){
  if(seen[i]||data[i*4+3]<=40)continue;
  let start=0,end=1;queue[0]=i;seen[i]=1;let x0=W,y0=H,x1=0,y1=0;
  while(start<end){const k=queue[start++],x=k%W,y=Math.floor(k/W);
   x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);
   for(const q of [k-1,k+1,k-W,k+W])if(q>=0&&q<N&&!seen[q]&&data[q*4+3]>40&&Math.abs(q%W-x)<=1){seen[q]=1;queue[end++]=q;}
  }
  if(end>200){const id=groups.length;for(let j=0;j<end;j++)ids[queue[j]]=id;groups.push({id,x:x0,y:y0,w:x1-x0+1,h:y1-y0+1,area:end});}
 }
 // Associate antialiased edge pixels with the closest connected character.
 // Preserve original RGBA; do not recolor or synthesize artwork.
 let start=0,end=0;const dist=new Uint8Array(N);
 for(let i=0;i<N;i++)if(ids[i]>=0)queue[end++]=i;
 while(start<end){const k=queue[start++];if(dist[k]>=4)continue;
  for(const q of [k-1,k+1,k-W,k+W])if(q>=0&&q<N&&ids[q]<0&&data[q*4+3]>0&&Math.abs(q%W-k%W)<=1){ids[q]=ids[k];dist[q]=dist[k]+1;queue[end++]=q;}
 }
 const rows=Array.from({length:layout==='atlas'?9:2},()=>[]);
 for(const g of groups){
  // Classify by the center, because jump apex can rise into the preceding row.
  const cy=g.y+g.h/2;
  const r=layout==='atlas'?[155,285,410,553,748,893,1045,1195].filter(v=>cy>=v).length:Math.min(1,Math.floor(cy/(H/2)));
  rows[r].push(g);
 }
 for(const row of rows)row.sort((a,b)=>a.x-b.x);
 const flat=rows.flat();
 for(const g of flat){
  const x=Math.max(0,g.x-4),y=Math.max(0,g.y-4),w=Math.min(W,g.x+g.w+4)-x,h=Math.min(H,g.y+g.h+4)-y;
  const out=Buffer.alloc(w*h*4);
  for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){const src=(y+yy)*W+x+xx;if(ids[src]===g.id)data.copy(out,(yy*w+xx)*4,src*4,src*4+4);}
  g.image=await sharp(out,{raw:{width:w,height:h,channels:4}}).png().toBuffer();
  g.crop={x,y,w,h};
 }
 console.log(path.basename(file),rows.map(r=>r.length));
 return {rows,flat,info};
}
async function main(){
 const report={format:{columns:8,rows:9,cellWidth:192,cellHeight:208,width:1536,height:1872,version:1},characters:[]};
 const characters=[{id:'01-folded-ear-scout',prefix:'01',name:'折耳巡游兽',mainScale:0.94},{id:'06-inkdrop-artisan',prefix:'06',name:'墨滴工匠',mainScale:1.03}];
 for(const pet of characters){
  const main=await components(path.join(root,'sources',pet.prefix+'-all-actions.png'),'atlas');
  const success=await components(path.join(root,'sources',pet.prefix+'-success.png'),'six');
  let idle=pet.prefix==='01'?await components(path.join(root,'sources','01-idle.png'),'six'):null;
  const allRows=main.rows.map(r=>({frames:r,scale:pet.mainScale,source:pet.prefix+'-all-actions.png'}));
  const sFrames=success.flat;
  // Fixed scale per source sequence; never independently fit individual frames.
  const sScale=pet.prefix==='01'?0.345:0.315;
  allRows[4]={frames:sFrames,scale:sScale,source:pet.prefix+'-success.png'};
  if(idle)allRows[0]={frames:idle.flat,scale:0.325,source:'01-idle.png'};
  if(pet.prefix==='01'){
   const leftRun=await components(path.join(root,'sources','01-left-run.png'),'eight');
   allRows[2]={frames:leftRun.flat,scale:0.36,source:'01-left-run.png'};
  }else{
   const thinking=await components(path.join(root,'sources','06-thinking.png'),'six');
   allRows[8]={frames:thinking.flat,scale:0.335,source:'06-thinking.png'};
  }
  const outDir=path.join(root,pet.id);fs.mkdirSync(path.join(outDir,'frames'),{recursive:true});
  const layers=[],records=[];
  for(let row=0;row<9;row++){
   const seq=allRows[row],expected=timing[row].length;
   if(seq.frames.length!==expected)throw Error(pet.id+' row '+row+' expected '+expected+' actual '+seq.frames.length);
   const rowRecords=[];
   for(let col=0;col<expected;col++){
    const g=seq.frames[col],w=Math.round(g.crop.w*seq.scale),h=Math.round(g.crop.h*seq.scale);
    const sprite=await sharp(g.image).resize(w,h,{kernel:'lanczos3'}).png().toBuffer();
    // Register ordinary grounded frames to baseline 184. Preserve a deliberate
    // ground-to-air-to-ground arc for success, with no per-frame rescaling.
    const jump=[0,12,30,15,0];
    const lift=row===4?jump[col]:0;
    const left=Math.round((CW-w)/2),top=184-h-lift;
    if(left<5||top<4||left+w>CW-5||top+h>CH-8)throw Error('sprite overflow '+pet.id+' '+row+':'+col+' '+JSON.stringify({w,h,left,top}));
    const frame=await sharp({create:{width:CW,height:CH,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite([{input:sprite,left,top}]).png().toBuffer();
    const file='frames/'+row+'-'+names[row]+'-'+col+'.png';
    fs.writeFileSync(path.join(outDir,file),frame);layers.push({input:frame,left:col*CW,top:row*CH});
    rowRecords.push({column:col,file,durationMs:timing[row][col],source:seq.source,sourceBounds:g.crop,scale:seq.scale,placement:{left,top,width:w,height:h},sha256:crypto.createHash('sha256').update(frame).digest('hex')});
   }
   records.push({row,action:names[row],label:labels[row],aieyes:mapping[row],frames:expected,cycleMs:timing[row].reduce((a,b)=>a+b,0),frameDurationsMs:timing[row],items:rowRecords});
  }
  await sharp({create:{width:CW*8,height:CH*9,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite(layers).png().toFile(path.join(outDir,'spritesheet.png'));
  const manifest={id:'aieyes-'+pet.id,displayName:'Aieyes · '+pet.name,description:'Aieyes 原创形象探索：9 行动作，57 个有效帧。2026-10-27。',spritesheetPath:'spritesheet.png',spriteVersionNumber:1};
  fs.writeFileSync(path.join(outDir,'pet.json'),JSON.stringify(manifest,null,2)+'\n');
  fs.writeFileSync(path.join(outDir,'animation.json'),JSON.stringify({pet:pet.id,...report.format,rows:records},null,2)+'\n');
  report.characters.push({id:pet.id,displayName:pet.name,rows:records});
 }
 fs.writeFileSync(path.join(root,'assembly-report.json'),JSON.stringify(report,null,2)+'\n');
}
main().catch(e=>{console.error(e);process.exitCode=1});
